-- drop-table OTTO_SHOPS (all rows are lost) [DESTRUCTIVE]
DROP TABLE "OTTO_SHOPS";

-- rebuild table COMPANIES: drop-column COMPANIES./TROTTO/OTTO_ID (column data is lost); drop-column COMPANIES./TROTTO/ACTIVE (column data is lost); drop-column COMPANIES./TROTTO/MAIN_SHOP (column data is lost); drop-foreign-key COMPANIES./TROTTO/MAIN_SHOP (references OTTO_SHOPS) [DESTRUCTIVE]
CREATE TABLE "COMPANIES#NEW" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "COUNTRY" TEXT NOT NULL,
  "STATUS" TEXT NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" INTEGER,
  "FOUNDED_ON" TEXT,
  CONSTRAINT "COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "COUNTRIES" ("COUNTRY_CODE"),
  CONSTRAINT "COMPANIES#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "COMPANIES#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "COMPANIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "COMPANIES#CK#COUNTRY" CHECK ("COUNTRY" IS NULL OR (length("COUNTRY") <= 2)),
  CONSTRAINT "COMPANIES#CK#STATUS" CHECK ("STATUS" IS NULL OR (length("STATUS") <= 10 AND "STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))),
  CONSTRAINT "COMPANIES#CK#CAPITAL" CHECK ("CAPITAL" IS NULL OR ("CAPITAL" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "COMPANIES#CK#FOUNDED_ON" CHECK ("FOUNDED_ON" IS NULL OR ("FOUNDED_ON" IS date("FOUNDED_ON")))
) STRICT;
INSERT INTO "COMPANIES#NEW" ("/RT/TENANT", "COMPANY_ID", "NAME", "COUNTRY", "STATUS", "CAPITAL", "FOUNDED_ON") SELECT "/RT/TENANT", "COMPANY_ID", "NAME", "COUNTRY", "STATUS", "CAPITAL", "FOUNDED_ON" FROM "COMPANIES";
DROP TABLE "COMPANIES";
ALTER TABLE "COMPANIES#NEW" RENAME TO "COMPANIES";

